-- UBL-only templates and append-only budgets; no global master or project changes.
CREATE TABLE ubl_configurations (
 id text PRIMARY KEY, customer_id bigint NOT NULL REFERENCES customers(id), source jsonb NOT NULL
);
CREATE TABLE ubl_source_documents (
 configuration_id text PRIMARY KEY REFERENCES ubl_configurations(id), filename text NOT NULL,
 sha256 text NOT NULL, content bytea NOT NULL
);
CREATE TABLE ubl_technical_versions (
 configuration_id text NOT NULL REFERENCES ubl_configurations(id), version integer NOT NULL,
 snapshot jsonb NOT NULL, effective_date date, notes text NOT NULL,
 PRIMARY KEY(configuration_id,version)
);
CREATE TABLE ubl_commercial_history (
 configuration_id text NOT NULL REFERENCES ubl_configurations(id), stage text NOT NULL,
 agreed_date date NOT NULL, snapshot jsonb NOT NULL,
 PRIMARY KEY(configuration_id,stage)
);
CREATE TABLE ubl_budget_versions (
 id uuid PRIMARY KEY, configuration_id text NOT NULL REFERENCES ubl_configurations(id),
 version integer NOT NULL, technical_version integer NOT NULL, snapshot jsonb NOT NULL,
 fingerprint text NOT NULL, request_key uuid NOT NULL UNIQUE, notes text NOT NULL,
 created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(configuration_id,version), FOREIGN KEY(configuration_id,technical_version) REFERENCES ubl_technical_versions(configuration_id,version)
);
CREATE TRIGGER immutable_ubl_configurations BEFORE UPDATE OR DELETE ON ubl_configurations FOR EACH ROW EXECUTE FUNCTION prevent_master_version_mutation();
CREATE TRIGGER immutable_ubl_source_documents BEFORE UPDATE OR DELETE ON ubl_source_documents FOR EACH ROW EXECUTE FUNCTION prevent_master_version_mutation();
CREATE TRIGGER immutable_ubl_technical_versions BEFORE UPDATE OR DELETE ON ubl_technical_versions FOR EACH ROW EXECUTE FUNCTION prevent_master_version_mutation();
CREATE TRIGGER immutable_ubl_commercial_history BEFORE UPDATE OR DELETE ON ubl_commercial_history FOR EACH ROW EXECUTE FUNCTION prevent_master_version_mutation();
CREATE TRIGGER immutable_ubl_budget_versions BEFORE UPDATE OR DELETE ON ubl_budget_versions FOR EACH ROW EXECUTE FUNCTION prevent_master_version_mutation();
